namespace strata::kernels {
namespace {
bool g_ple_native_bf16 = false;     // the CUDA TU's defaults
bool g_ple_native_postops = false;
}  // namespace
void ple_set_native_bf16(bool enabled) { g_ple_native_bf16 = enabled; }
void ple_set_native_postops(bool enabled) { g_ple_native_postops = enabled; }
bool ple_native_postops_enabled() { return g_ple_native_postops; }
uint64_t ple_block_scratch_bytes() {
    // Pure host arithmetic, ported from the CUDA TU (NG_HC_DIM 10240, NG_N_EMBD 2560, NG_HC 4).
    const size_t f = (size_t) (5 * 10240 + 2560 + 4) * sizeof(float);
    const size_t q = (size_t) (2560 / 32) * 34;
    const size_t e = (size_t) 2560 * sizeof(uint16_t);
    return ((f + 15) & ~(size_t) 15) + ((q + 15) & ~(size_t) 15) + e + 256;
}
void ple_block(const float* emb, const float* hidden, const float* hist_rows, const PleWeights& w, PleOut& out, void* scratch, void* stream) {
    // Composition of this family's entries, mirroring ple.cu's stage order and
    // scratch carve (see ple_block_scratch_bytes): five hc_dim buffers (key,
    // query, norm, gated, conv), one n_embd (value), one hc (gate), then the
    // Q8_0 activation image and the BF16 embedding copy, 16-byte aligned.
    constexpr int64_t n_embd = NG_N_EMBD, hc_dim = NG_HC_DIM, hc = NG_HC;
    const bool native_key = w.key_native_data != nullptr && w.key_bf16 == nullptr;
    if (native_key && (!emb || !hidden || !hist_rows || !out.result || !scratch || !stream ||
                       w.key_native_type < 0 || !w.key_native_q8_1))
        throw std::invalid_argument("ple_block: native key requires Q2_0, IQ3_XXS or IQ4_XS weights, input/output, private scratch and explicit stream");
    if (scratch == nullptr) dense_detail::bad_shape("ple_block: scratch is null; the caller owns it");
    const struct { const float* pointer; size_t count; const char* name; } exports[] = {
        {out.key, (size_t) hc_dim, "key"}, {out.value, (size_t) n_embd, "value"},
        {out.gate, (size_t) hc, "gate"}, {out.gated, (size_t) hc_dim, "gated"},
        {out.normalized, (size_t) hc_dim, "normalized"}, {out.conv, (size_t) hc_dim, "conv"},
        {out.result, (size_t) hc_dim, "result"}};
    for (const auto& item : exports) {
        if (item.pointer == nullptr) continue;
        const auto x = reinterpret_cast<uintptr_t>(item.pointer), y = reinterpret_cast<uintptr_t>(scratch);
        if (x < y + (size_t) ple_block_scratch_bytes() && y < x + item.count * sizeof(float))
            throw std::invalid_argument(std::string("ple_block: output ") + item.name + " overlaps scratch");
    }
    const size_t float_bytes = (size_t) (5 * hc_dim + n_embd + hc) * sizeof(float);
    const size_t q8_bytes = (size_t) (n_embd / 32) * 34;
    uint8_t* base = (uint8_t*) scratch;
    float* d_key = (float*) base;
    float* d_query = d_key + hc_dim;
    float* d_norm = d_query + hc_dim;
    float* d_gated = d_norm + hc_dim;
    float* d_conv = d_gated + hc_dim;
    float* d_value = d_conv + hc_dim;
    float* d_gate = d_value + n_embd;
    uint8_t* d_act = base + ((float_bytes + 15) & ~(size_t) 15);
    uint16_t* d_emb16 = (uint16_t*) (d_act + ((q8_bytes + 15) & ~(size_t) 15));

    // key projection
    if (w.key_bf16 != nullptr) {
        bf16_gemv_fp32_mmvf(emb, w.key_bf16, d_key, n_embd, hc_dim, stream);
    } else if (native_key) {
        native_quantize_q8_1(emb, w.key_native_q8_1, (int) n_embd, 1, stream);
        native_mmvq(w.key_native_type, w.key_native_data, w.key_native_q8_1, d_key, (int) n_embd, (int) hc_dim,
                    1, stream);
    } else {
        quantize_q8_0(emb, d_act, n_embd, stream);
        s2_gemv_q8(d_act, w.key_codes, w.key_scales, d_key, n_embd, hc_dim, 8, stream);
    }
    if (!g_ple_native_postops) {
        const float eps = NG_RMS_EPS;
        const metal::KernelArg kargs[] = {metal::buf(d_key), metal::buf(w.norm_key), metal::buf(d_key),
                                          metal::val(eps)};
        dense_detail::launch_sync(dense_detail::stream_of(stream), "ple_gnorm_k", (uint32_t) hc * 256, 256,
                                  kargs, 4, false);
        const metal::KernelArg qargs[] = {metal::buf(hidden), metal::buf(w.norm_query), metal::buf(d_query),
                                          metal::val(eps)};
        dense_detail::launch_sync(dense_detail::stream_of(stream), "ple_gnorm_k", (uint32_t) hc * 256, 256,
                                  qargs, 4, false);
    }
    // value projection
    if (g_ple_native_bf16) {
        bf16_gemv_fp32_mmvf(emb, w.value_bf16, d_value, n_embd, n_embd, stream);
    } else {
        f32_to_bf16_bulk(emb, d_emb16, n_embd, stream);
        bf16_gemv(d_emb16, w.value_bf16, d_value, n_embd, n_embd, stream);
    }
    const float* normalized_key = d_key;
    if (g_ple_native_postops) {
        NativePlePostopsBuffers buffers{d_query, d_norm, d_gate, d_gated, d_norm, d_conv, out.result};
        native_ple_postops(d_key, hidden, d_value, hist_rows, w, buffers, stream);
        normalized_key = d_query;
    } else {
        const float inv_sqrt_n = 1.0f / std::sqrt((float) n_embd);
        const metal::KernelArg gargs[] = {metal::buf(d_key), metal::buf(d_query), metal::buf(d_gate),
                                          metal::val(inv_sqrt_n)};
        dense_detail::launch_sync(dense_detail::stream_of(stream), "ple_gate_k", (uint32_t) hc * 256, 256,
                                  gargs, 4, false);
        {
            const metal::KernelArg args[] = {metal::buf(d_value), metal::buf(d_gate), metal::buf(d_gated)};
            dense_detail::launch_sync(dense_detail::stream_of(stream), "ple_bcast_k", (uint32_t) hc_dim, 256,
                                      args, 3, false);
        }
        const float eps = NG_RMS_EPS;
        const metal::KernelArg nargs[] = {metal::buf(d_gated), metal::buf(w.norm_conv), metal::buf(d_norm),
                                          metal::val(eps)};
        dense_detail::launch_sync(dense_detail::stream_of(stream), "ple_gnorm_k", (uint32_t) hc * 256, 256,
                                  nargs, 4, false);
        {
            const metal::KernelArg args[] = {metal::buf(hist_rows), metal::buf(d_norm), metal::buf(w.conv1d_f16),
                                             metal::buf(d_conv)};
            dense_detail::launch_sync(dense_detail::stream_of(stream), "ple_conv_k", (uint32_t) hc_dim, 256,
                                      args, 4, false);
        }
        {
            const metal::KernelArg args[] = {metal::buf(hidden), metal::buf(d_gated), metal::buf(d_conv),
                                             metal::buf(out.result)};
            dense_detail::launch_sync(dense_detail::stream_of(stream), "ple_add3_k", (uint32_t) hc_dim, 256,
                                      args, 4, false);
        }
    }
    // intermediates for the oracle comparison, as ple.cu exports them
    if (out.key) copy_from_mapped(out.key, normalized_key, hc_dim, stream);
    if (out.value) copy_from_mapped(out.value, d_value, n_embd, stream);
    if (out.gate) copy_from_mapped(out.gate, d_gate, hc, stream);
    if (out.gated) copy_from_mapped(out.gated, d_gated, hc_dim, stream);
    if (out.normalized) copy_from_mapped(out.normalized, d_norm, hc_dim, stream);
    if (out.conv) copy_from_mapped(out.conv, d_conv, hc_dim, stream);
}
void ple_history_advance(float* hist, const float* normalized, void* stream) {
    // One thread per channel (ple.metal ple_hist_k): the in-place shift is
    // well-defined because each channel's 9 row-fastest values are owned by
    // one thread, exactly the CUDA kernel's argument.
    if (hist == nullptr || normalized == nullptr)
        throw std::invalid_argument("ple_history_advance: null history or normalized input");
    const auto h0 = reinterpret_cast<uintptr_t>(hist), n0 = reinterpret_cast<uintptr_t>(normalized);
    if (h0 < n0 + (size_t) NG_HC_DIM * 4 && n0 < h0 + (size_t) NG_HIST * NG_HC_DIM * 4)
        throw std::invalid_argument("ple_history_advance: history and normalized input overlap");
    const metal::KernelArg args[] = {metal::buf(hist), metal::buf(normalized)};
    dense_detail::launch_sync(dense_detail::stream_of(stream), "ple_hist_k", NG_HC_DIM, 256, args, 2, false);
}
bool ple_block_available() {
    return true;  // the Metal backend has exactly one device; the CUDA TU answers device-count > 0
}
}  // namespace strata::kernels

